        return image
    }
}

/// A line icon tinted with the current foreground style.
struct Icon: View {
    let name: IconName
    var size: CGFloat = 16

    var body: some View {
        Image(nsImage: name.image)
            .resizable()
            .renderingMode(.template)
            .interpolation(.high)
            .frame(width: size, height: size)
            .accessibilityHidden(true)
    }
}
